122:     if (audio.state === 'suspended') audio.resume();
123:     const o = audio.createOscillator(), g = audio.createGain();
124:     o.type = 'sine'; o.frequency.value = freq; g.gain.value = .045;
125:     g.gain.exponentialRampToValueAtTime(.001, audio.currentTime + duration);
126:     o.connect(g); g.connect(audio.destination); o.start(); o.stop(audio.currentTime + duration);
127:   } catch (_) { /* audio is optional */ }
128: }
129: function targetForInteraction() {
