const { createRequire } = require('node:module');
const { join } = require('node:path');
const { mkdirSync } = require('node:fs');
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const requireRuntime = createRequire(join(runtime, 'package.json'));
const { chromium } = requireRuntime('playwright');
const out = '/tmp/opencode/screens';
mkdirSync(out, { recursive: true });

const sleep = ms => new Promise(r => setTimeout(r, ms));

(async () => {
  const browser = await chromium.launch({ headless: true, executablePath: '/usr/bin/chromium', args: ['--no-sandbox'] });
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('pageerror: ' + e.message));
  page.on('console', m => { if (m.type() === 'error' && !m.text().includes('favicon')) errors.push('console: ' + m.text()); });
  await page.goto('http://localhost:3002', { waitUntil: 'load' });
  await page.evaluate(() => localStorage.clear());
  await page.reload({ waitUntil: 'load' });
  const phase = () => page.evaluate(() => window.__ramp.world.phase);
  const waitPhase = async (n, timeout = 45000) => {
    await page.waitForFunction(n => window.__ramp && window.__ramp.world.phase >= n, n, { timeout, polling: 100 });
  };
  await waitPhase(1);
  console.log('arrived phase 1');
  await page.evaluate(() => { window.__ramp.teleport(588, 474); window.__ramp.interact(); });
  await waitPhase(3);
  console.log('phase 3');
  await page.evaluate(() => { window.__ramp.teleport(700, 520); window.__ramp.interact(); });
  await page.waitForFunction(() => window.__ramp.world.phase === 4, null, { timeout: 45000, polling: 100 });
  console.log('phase 4, paxOut', await page.evaluate(() => window.__ramp.world.paxOut));
  await page.screenshot({ path: join(out, 'e2e-assist.png') });
  await page.evaluate(() => { window.__ramp.teleport(820, 548); window.__ramp.interact(); });
  await waitPhase(5);
  await sleep(2200);
  console.log('boarding snapshot', await page.evaluate(() => ({ paxIn: window.__ramp.world.paxIn, loaded: window.__ramp.world.loaded, bagStates: window.__ramp.inboundBags.map(b => b.state) })));
  await page.screenshot({ path: join(out, 'e2e-boarding.png') });
  await page.waitForFunction(() => window.__ramp.world.phase === 6, null, { timeout: 45000, polling: 100 });
  console.log('phase 6', await page.evaluate(() => ({ paxIn: window.__ramp.world.paxIn, loaded: window.__ramp.world.loaded })));
  await page.evaluate(() => { window.__ramp.teleport(700, 520); window.__ramp.interact(); });
  await waitPhase(8);
  console.log('phase 8');
  await page.evaluate(() => { window.__ramp.teleport(365, 740); window.__ramp.interact(); });
  await waitPhase(9);
  await sleep(5000);
  await page.screenshot({ path: join(out, 'e2e-pushback.png') });
  await page.waitForFunction(() => !document.getElementById('completeOverlay').classList.contains('hidden'), null, { timeout: 30000, polling: 100 });
  console.log('complete', await page.evaluate(() => ({ reward: document.getElementById('reward').textContent, score: document.getElementById('scoreText').textContent, money: localStorage.getItem('ramp-money'), op: localStorage.getItem('ramp-operation') })));
  await page.screenshot({ path: join(out, 'e2e-complete.png') });
  await page.click('#nextFlightBtn');
  await sleep(800);
  console.log('next flight', await page.evaluate(() => ({ phase: window.__ramp.world.phase, hidden: document.getElementById('completeOverlay').classList.contains('hidden'), flight: document.getElementById('flightNo').textContent })));
  console.log('errors', errors);
  await browser.close();
})().catch(error => { console.error(error); process.exitCode = 1; });

